            more:CreateRadio(order,
                function() return filters.sort == order end,
                function() filters.sort = order end)
        end
        rootDescription:CreateButton("Reset", function()
            filters.quests, filters.rares, filters.treasures = true, false, false
        end)
    end)
    return dropdown
